/**
 * Overall profile — a deterministic synthesis of a chart.
 *
 * Nothing here is random or generated by AI. The overview is assembled from the
 * traditional meanings in src/data using a few well-known reading techniques:
 *
 *  1. Core summary — Life Path (journey), Expression (talents), Soul Urge
 *     (inner desire) and Personality (outer impression) read together.
 *  2. Repeated numbers — a number appearing more than once in the five core
 *     positions is traditionally read as an amplified theme.
 *  3. Master numbers — any 11, 22 or 33 is highlighted.
 *  4. Number families — numerologists often group the digits by temperament:
 *       1, 5, 7  — independent, thinking numbers ("mind")
 *       2, 4, 8  — practical, building numbers ("structure")
 *       3, 6, 9  — creative, feeling numbers ("heart")
 *     (Master numbers count with their root: 11 → 2, 22 → 4, 33 → 6.)
 *     The family that dominates the chart, and whether the Life Path and
 *     Expression share a family, describe the chart's overall balance.
 *  5. Inner vs outer — comparing Soul Urge and Personality.
 *  6. Karmic lessons — digits missing from the name.
 */

import { NUMBER_MEANINGS } from '../../data/numbers';
import { KARMIC_LESSONS } from '../../data/cycles';
import { rootDigit, isMasterNumber } from './reduce';
import type { NumerologyChart } from './calculate';

export type Family = 'mind' | 'structure' | 'heart';

export const FAMILIES: Record<Family, { name: string; digits: number[]; description: string }> = {
  mind: {
    name: 'Mind',
    digits: [1, 5, 7],
    description: 'independent, curious and thoughtful — drawn to ideas, freedom and understanding',
  },
  structure: {
    name: 'Structure',
    digits: [2, 4, 8],
    description: 'practical, steady and constructive — drawn to building, organising and partnership',
  },
  heart: {
    name: 'Heart',
    digits: [3, 6, 9],
    description: 'creative, caring and expressive — drawn to people, beauty and meaning',
  },
};

export function familyOf(n: number): Family {
  const root = rootDigit(n);
  if ([1, 5, 7].includes(root)) return 'mind';
  if ([2, 4, 8].includes(root)) return 'structure';
  return 'heart';
}

export interface ProfileInsight {
  title: string;
  text: string;
}

export interface Profile {
  headline: string;
  summary: string[];
  insights: ProfileInsight[];
  familyCounts: Record<Family, number>;
  dominantFamily: Family | null;
}

const lower = (s: string) => s.toLowerCase();
const listJoin = (items: string[]) =>
  items.length <= 1 ? items.join('') : `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
const theTitle = (n: number) => NUMBER_MEANINGS[n].title.replace(/^The /, 'the ');

export function buildProfile(chart: NumerologyChart): Profile {
  const { lifePath, expression, soulUrge, personality, birthday } = chart;
  const lp = NUMBER_MEANINGS[lifePath.value];
  const ex = NUMBER_MEANINGS[expression.value];
  const su = NUMBER_MEANINGS[soulUrge.value];
  const pe = NUMBER_MEANINGS[personality.value];
  const bd = NUMBER_MEANINGS[birthday.value];

  const headline =
    lifePath.value === expression.value
      ? `${lp.title}, through and through`
      : `${lp.title} with the gifts of ${theTitle(expression.value)}`;

  const summary = [
    `Your Life Path ${lifePath.value} describes a journey shaped by ${listJoin(lp.keywords.slice(0, 3).map(lower))}. ` +
      `It is the broad road of your life — the lessons you keep returning to and the person you are growing into.`,
    `Along that road you carry the talents of Expression ${expression.value}: ${listJoin(ex.keywords.slice(0, 3).map(lower))}. ` +
      `Your Birthday number ${birthday.value} adds a particular gift for ${lower(bd.keywords[0])}.`,
    `At heart, your Soul Urge ${soulUrge.value} longs for ${listJoin(su.keywords.slice(0, 2).map(lower))}, ` +
      `while people who are just meeting you tend to notice the ${listJoin(pe.keywords.slice(0, 2).map(lower))} of your Personality ${personality.value}.`,
  ];

  const insights: ProfileInsight[] = [];
  const core = [lifePath, expression, soulUrge, personality, birthday];

  // 2. Repeated numbers
  const counts = new Map<number, number>();
  for (const n of core) counts.set(n.value, (counts.get(n.value) ?? 0) + 1);
  for (const [value, count] of [...counts.entries()].sort((a, b) => b[1] - a[1])) {
    if (count < 2) continue;
    const m = NUMBER_MEANINGS[value];
    insights.push({
      title: `A strong ${value}`,
      text:
        `The number ${value} appears ${count === 2 ? 'twice' : `${count} times`} among your core numbers. ` +
        `Repeated numbers are traditionally read as amplified themes, so the qualities of ${theTitle(value)} — ` +
        `${listJoin(m.keywords.map(lower))} — are likely to feel especially central for you.`,
    });
  }

  // 3. Master numbers
  const masters = [...new Set(core.filter((n) => isMasterNumber(n.value)).map((n) => n.value))];
  if (masters.length) {
    insights.push({
      title: masters.length === 1 ? `Master number ${masters[0]}` : `Master numbers ${listJoin(masters.map(String))}`,
      text:
        `Your chart contains ${masters.length === 1 ? 'the master number' : 'the master numbers'} ${listJoin(masters.map(String))}. ` +
        `Master numbers are traditionally seen as carrying heightened potential along with heightened sensitivity — ` +
        `a call to grow into something larger, often gradually and with maturity. On days when that feels like too much, ` +
        `the root number (${listJoin(masters.map((m) => `${m} → ${rootDigit(m)}`))}) offers a gentler, more grounded expression.`,
    });
  }

  // 4. Number families
  const familyCounts: Record<Family, number> = { mind: 0, structure: 0, heart: 0 };
  for (const n of core) familyCounts[familyOf(n.value)]++;
  const sorted = (Object.entries(familyCounts) as [Family, number][]).sort((a, b) => b[1] - a[1]);
  const dominantFamily = sorted[0][1] >= 3 ? sorted[0][0] : null;
  if (dominantFamily) {
    const f = FAMILIES[dominantFamily];
    insights.push({
      title: `A ${f.name.toLowerCase()}-led chart`,
      text:
        `${sorted[0][1]} of your five core numbers belong to the ${f.name} family (${f.digits.join(', ')}), ` +
        `suggesting a nature that is ${f.description}.`,
    });
  } else {
    insights.push({
      title: 'A well-balanced chart',
      text:
        'Your core numbers are spread across the three number families — Mind (1, 5, 7), Structure (2, 4, 8) and Heart (3, 6, 9). ' +
        'A balanced chart is traditionally read as versatility: you can draw on thought, practicality and feeling as each situation requires.',
    });
  }

  const lpFamily = familyOf(lifePath.value);
  const exFamily = familyOf(expression.value);
  insights.push(
    lifePath.value === expression.value
      ? {
          title: 'Path and talents in unison',
          text: `Your Life Path and Expression are the same number. Your natural abilities fit your life’s direction closely, which can give a strong sense of purpose — the gift is focus, the lesson is to keep growing beyond what comes easily.`,
        }
      : lpFamily === exFamily
        ? {
            title: 'Path and talents in harmony',
            text: `Your Life Path ${lifePath.value} and Expression ${expression.value} share the ${FAMILIES[lpFamily].name} family, so your talents tend to support your journey naturally.`,
          }
        : {
            title: 'Path and talents in creative tension',
            text: `Your Life Path ${lifePath.value} (${FAMILIES[lpFamily].name}) and Expression ${expression.value} (${FAMILIES[exFamily].name}) come from different number families. This is traditionally seen as a productive tension: your talents stretch you in directions your path might not take on its own, making you more rounded.`,
          },
  );

  // 5. Inner vs outer
  insights.push(
    soulUrge.value === personality.value
      ? {
          title: 'What you feel is what people see',
          text: `Your Soul Urge and Personality are both ${soulUrge.value}. What you want inwardly and how you come across are closely aligned — people tend to read you accurately.`,
        }
      : {
          title: 'Inner world and outer face',
          text: `Inside, your Soul Urge ${soulUrge.value} seeks ${lower(su.keywords[0])}; outwardly, your Personality ${personality.value} shows ${lower(pe.keywords[0])}. Those who know you well may discover a side of you that first impressions miss.`,
        },
  );

  // 6. Karmic lessons
  if (chart.missingNumbers.length) {
    insights.push({
      title: chart.missingNumbers.length === 1 ? 'A karmic lesson' : 'Karmic lessons',
      text:
        `The number${chart.missingNumbers.length > 1 ? 's' : ''} ${listJoin(chart.missingNumbers.map(String))} ` +
        `${chart.missingNumbers.length > 1 ? 'do' : 'does'} not appear in the letters of your name. Traditionally, missing numbers point to qualities to develop consciously: ` +
        chart.missingNumbers.map((n) => `${n} — ${lower(KARMIC_LESSONS[n].replace(/\.$/, ''))}`).join('; ') +
        '.',
    });
  } else {
    insights.push({
      title: 'Every number present',
      text: 'All nine numbers appear in the letters of your name. Traditionally this is read as a well-rounded set of inner resources, with no karmic lessons to make up.',
    });
  }

  return { headline, summary, insights, familyCounts, dominantFamily };
}
